(()=>{'use strict';
let bands=[];const rows=window.UHE_SIN||[],cfg=window.UHE_CONFIG,expected=[58,117,239,94,26];
const audit=[{n:56,teif:1.7012142857142858,ip:3.8253392857142856},{n:117,teif:1.8437179487179487,ip:3.64125641025641},{n:239,teif:1.5908033472803347,ip:3.706623430962343},{n:94,teif:2.681287234042553,ip:3.4775531914893616},{n:26,teif:2.1074615384615383,ip:2.399}];
window.Projection={refs:()=>bands.map(b=>b.ref),parameters:()=>({fator_teif_projecao:Number($('projectTeif').value),fator_ip_projecao:Number($('projectIp').value)}),apply};
function apply(){try{const t=$('projectTeif').value,i=$('projectIp').value;if(t===''||i==='')throw Error('Informe os dois fatores.');bands=ProjectionModel.forecast(rows,Engine.refs,Number(t),Number(i));$('projectTable').innerHTML=bands.map((b,k)=>`<tr><td>${labels[k]}</td><td>${b.plants}</td><td>${b.n}</td><td>${fmt(b.teif,6)}</td><td>${fmt(b.ip,6)}</td><td>${fmt(b.disp,6)}</td><td>${fmt(b.disp-Engine.availability(Engine.refs[k][1],Engine.refs[k][2]),6)}</td></tr>`).join('');const used=rows.filter(r=>r.include);$('projectStatus').textContent=used.length+' usinas / '+rows.length+' registros SIN · '+used.reduce((s,r)=>s+r.n,0)+' UGs · taxas ONS: setembro/2026 · horizonte: janeiro/2028. Fatores TEIF/IP: '+t+' / '+i+'.';document.dispatchEvent(new CustomEvent('projection:changed'));}catch(e){$('projectStatus').textContent='Projeção indisponível: '+e.message}}
$('projectTeif').value=cfg.forecastTeif??1;$('projectIp').value=cfg.forecastIp??1;$('projectApply').onclick=apply;
$('projectAudit').innerHTML=audit.map((a,k)=>`<tr><td>${labels[k]}</td><td>${a.n} / ${expected[k]}</td><td>${fmt(a.teif,6)} / ${fmt(Engine.refs[k][1],3)}</td><td>${fmt(a.ip,6)} / ${fmt(Engine.refs[k][2],3)}</td><td>${k?'Coincide a 3 casas':'Divergência no Anexo I'}</td></tr>`).join('');
function list(){const q=$('sinFilter').value.toLowerCase();$('sinRows').innerHTML=rows.filter(r=>(r.name+' '+r.onsName+' '+r.ceg).toLowerCase().includes(q)).map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.ceg)}</small></td><td>${r.band||'Múltiplas / pendente'}</td><td>${r.n||'—'}</td><td>${r.teif===null?'—':fmt(r.teif,6)}</td><td>${r.ip===null?'—':fmt(r.ip,6)}</td><td>${esc(r.date||'—')}</td><td>${r.include?'Incluída':'Excluída'}</td><td>${esc(r.reason)}</td></tr>`).join('')}
$('sinFilter').oninput=list;$('projectExport').onclick=()=>download('referencia_projetada_jan2028.csv','\uFEFF'+csv([['faixa','usinas','ugs','teif_pct','ip_pct','disponibilidade_pct','hipotese'],...bands.map(b=>[b.band,b.plants,b.n,b.teif,b.ip,b.disp,'Persistência ajustada por fatores; não homologada'])]),'text/csv;charset=utf-8');
list();apply();
})();
